# French typography: a narrow no-break space before ? ! : ; and inside « » (as in wave2_core_fr_de.py).
import re as _re
def _fr(s):
    s = _re.sub(r' ([?!:;])', ' \\1', s)
    return s.replace('« ', '« ').replace(' »', ' »')
T = {k: [_fr(v[0]), v[1]] for k, v in T.items()}
